<template>
    <div>
        <h1>Вход</h1>
        <div class="formLogin">
            <input type="text" v-model="dataUser.name">
            <input type="password" v-model="dataUser.password">
            <button v-on:click="LogInUser" class="buttonLogin">Войти</button>
        </div>
    </div>
</template>

<script>
export default{
    name:'formLogInVue',
    data(){
        return{
            dataUser:{
                name:"", 
                password:"",
                typeUser:"", 
            }, 
            requestOptionsPost:{ 
                method: 'POST',
                mode: 'cors', 
                headers: {
                    "Content-Type": "application/json",},
                body: {},
            },
        }
    },
    methods:{
        LogInUser(){
            if(this.dataUser.password!="" && this.dataUser.name !=""){
                this.requestOptionsPost.body = JSON.stringify(this.dataUser)
                fetch('https://qg8cgwhx-3000.euw.devtunnels.ms/userLogIn', this.requestOptionsPost)
                    .then(res => {
                        res.text().then(function(value){
                            sessionStorage.setItem("typeUser", value)
                        })
                        sessionStorage.setItem("userName", this.dataUser.name)
                        location.reload()
                    })
            }else if(this.dataUser.password=="" || this.dataUser.name ==""){
                alert("Вы оставили обязательное поле пустым");
            }
        }
    },
    
}
</script>

<style>
.formLogin{
    display: flex;
    flex-direction: column;
    justify-content: space-around;
    align-items:center;

    width: 100%;
    height: 20vw;
}
.buttonLogin{
    margin-bottom: 200px;
    background-color: darkslategray;
    color: aliceblue;
    width: 125px;
    height: 50px;
    border: 1px solid rgba(0, 0, 0, 1);
    border-radius: 10px;
}

</style>