<template>
  <div class="contentDiv">
    <div class="serchDiv">
      <input type="text" class="serchInput" v-model="serchData.serchStr"> 
      <button class="serchButton"><img src="../assets/serch.png" alt="" class="sercPng" @click="serch()"></button>
    </div>

  </div>
  <div class="offers">
    <div class="offer" v-for="announcements in dataAnnouncements" :key="announcements.id">
          <div class="name">
            <h2>{{ announcements.name }}</h2>
            <div>{{announcements.userName}}</div>
          </div>
          <details>
            <summary>Читать больше</summary>
            <div class="pre">{{ announcements.description }}</div>
          </details>
    </div>
  </div>
</template>

<script>
export default {
  name: 'SerchingVue',
  data(){
    return{
      dataAnnouncements: [], 
      isPopup: false, 
      serchData:{
        serchStr:"", 
        userName:"", 
      }, 
      requestOptionsPost:{ 
        method: 'POST',
        mode: 'cors', 
        headers: {"Content-Type": "application/json",},
        body: {},
      },
    }
  }, 
  mounted(){
      fetch('https://qg8cgwhx-3000.euw.devtunnels.ms/getAllAnnouncements')
      .then(response => response.json())
      .then(data => {
          this.dataAnnouncements = data
          this.serchData.userName = sessionStorage.getItem("userName")
      })
  } , 
  methods:{
    openPopup() {
      this.isPopup = true
    }, 
    closePopup() {
      this.isPopup = false
    }, 
    serch(){
      this.serchData.userName = sessionStorage.getItem("userName")
      
      if(this.serchData!="" && this.serchData.userName != null){
        this.requestOptionsPost.body = JSON.stringify(this.serchData)
        fetch('https://qg8cgwhx-3000.euw.devtunnels.ms/serch', this.requestOptionsPost)
          .then(res => {
            res.text().then(data => {
              if (JSON.parse(data) == []){
                alert("Ничего не найдено")
              }else{
                this.dataAnnouncements = JSON.parse(data)
                console.log(this.dataAnnouncements);
              }
            })
          })
      } else if (this.serchData.userName == null){
        alert("Сначала войдите в аккаунт")
      }
    }
  }
}
</script>

