<template>

        <div class="profile">
            <div v-if="isAuth">
                привет, {{userName}}
                <div v-if="typeUser != 'Entrepreneur'">
                    <button @click="isCreatAnnouncement = !isCreatAnnouncement">Создать своё объявление</button>
                    <div class="createAnnouncement" v-if="isCreatAnnouncement">
