            },
        }
    }, 
    mounted(){
        if (sessionStorage.getItem("userName") != null){
            this.isAuth = true
            this.userName = sessionStorage.getItem("userName")
            this.typeUser = sessionStorage.getItem("typeUser")
            this.dataAnnouncement.userName = sessionStorage.getItem("userName")
        }
    }, 
