            && this.dataAnnouncement.name!="" 
            && this.dataAnnouncement.price!="" 
            && this.dataAnnouncement.userName!=""){
                this.requestOptionsPost.body = JSON.stringify(this.dataAnnouncement)
                fetch('https://qg8cgwhx-3000.euw.devtunnels.ms/cresteAnnouncements', this.requestOptionsPost)
                    .then(res => {
                        console.log(res)
                    })
                console.log(this.dataUser);
            }else{
